// Eclate la reponse de l'endpoint (un item contenant pages[]) en N items.
const res = $input.first().json;
const pages = res.pages || [];
return pages.map((p) => ({ json: p }));

// "Run Once for All Items" : construit la requete Claude pour chaque page.
// Generique : gere activity_city, city, department, region.
const pages = $input.all();
const out = [];
for (const item of pages) {
  const p = item.json;
  const il = p.internalLinks || {};
  const internal = [];
  for (const v of Object.values(il)) {
    if (!v) continue;
    if (Array.isArray(v)) { for (const x of v) if (x && x.path) internal.push(x); }
    else if (v.path) internal.push(v);
  }
  for (const c of (p.clubs || [])) internal.push(c);
  const internalList = internal.map((x) => '- ' + x.name + ' -> ' + x.path).join('\n');
  const externalList = (p.externalLinks || []).map((x) => '- ' + x.label + ' -> ' + x.url).join('\n');

  let subject;
  if (p.page_type === 'activity_city') subject = 'la pratique du ' + p.activity + ' a ' + p.city;
  else if (p.page_type === 'city') subject = 'les clubs de voile a ' + p.city + ' (' + p.department + ', ' + p.region + ')';
  else if (p.page_type === 'department') subject = 'les clubs de voile dans le departement ' + p.department + ' (' + p.region + ')';
  else if (p.page_type === 'region') subject = 'les clubs de voile dans la region ' + p.region;
  else subject = 'les clubs de voile';

  const system =
    "Tu es un redacteur SEO expert pour ClubsVoile.fr, annuaire des clubs de voile en France. " +
    "Tu ecris un contenu editorial unique, factuel et naturel en francais, optimise autour du mot-cle principal. " +
    "Regles STRICTES : " +
    "1) intro_html = 2 a 3 paragraphes <p> + un sous-titre <h2>, 120-220 mots, sans recopier de listes brutes. " +
    "2) Insere 3 a 6 LIENS INTERNES en utilisant UNIQUEMENT les chemins fournis, sous la forme <a href=\"/chemin\">ancre</a>. N'invente JAMAIS d'URL interne. " +
    "3) Insere 1 a 2 LIENS EXTERNES d'autorite en utilisant uniquement les URLs externes fournies. " +
    "4) meta_title <= 60 caracteres ; meta_description <= 155 caracteres ; accrocheurs, avec le mot-cle. " +
    "5) faq = 2 a 3 questions/reponses utiles et factuelles. " +
    "Ne mentionne que des faits deduits du contexte. N'invente aucun fait.";

  const user =
    'Sujet de la page : ' + subject + '\n' +
    'Type : ' + p.page_type + '\n' +
    (p.city ? 'Ville : ' + p.city + '\n' : '') +
    (p.department ? 'Departement : ' + p.department + '\n' : '') +
    (p.region ? 'Region : ' + p.region + '\n' : '') +
    (p.activity ? 'Activite : ' + p.activity + '\n' : '') +
    'Nombre de clubs : ' + (p.clubsCount != null ? p.clubsCount : (p.clubs || []).length) + '\n\n' +
    'LIENS INTERNES disponibles (utilise les chemins exacts) :\n' + (internalList || '(aucun)') + '\n\n' +
    "LIENS EXTERNES d'autorite disponibles :\n" + (externalList || '(aucun)') + '\n';

  const body = {
    model: 'claude-haiku-4-5', max_tokens: 1200, system,
    messages: [{ role: 'user', content: user }],
    output_config: { format: { type: 'json_schema', schema: {
      type: 'object', additionalProperties: false,
      properties: {
        meta_title: { type: 'string' }, meta_description: { type: 'string' }, intro_html: { type: 'string' },
        faq: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { q: { type: 'string' }, a: { type: 'string' } }, required: ['q', 'a'] } },
      }, required: ['meta_title', 'meta_description', 'intro_html', 'faq'],
    } } },
  };
  out.push({ json: { path: p.path, page_type: p.page_type, body } });
}
return out;

const responses = $input.all();
const prepared = $('Preparer la requete Claude').all();
const out = [];
for (let i = 0; i < responses.length; i++) {
  const meta = prepared[i] ? prepared[i].json : null;
  if (!meta || !meta.path) continue;
  let parsed;
  try { parsed = JSON.parse(responses[i].json.content?.[0]?.text ?? ''); } catch (e) { continue; }
  if (!parsed || !parsed.meta_title) continue;
  out.push({ json: { path: meta.path, page_type: meta.page_type, meta_title: parsed.meta_title, meta_description: parsed.meta_description, intro_html: parsed.intro_html, faq: parsed.faq || [], status: 'published' } });
}
return out;
